/// <summary>
/// extends SysOperationServiceController
/// </summary>
internal final class AVAICPriceTransferController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVAICPriceTransferController    controller;
    AVAICPriceTransferContract      contract;

    controller = new AVAICPriceTransferController(classStr(AVAICPriceTransferService),
                                       methodStr(AVAICPriceTransferService, process),
                                       SysOperationExecutionMode::Synchronous);
    contract = controller.getDataContractObject();
    if (_args.record() && _args.dataset() == tableNum(InterCompanyTradingPartner))
    {
        contract.parmICTradingPartner(_args.record());
    }
    controller.startOperation();
}

/// <summary>
/// Returns default classDescription
/// </summary>
/// <returns>ClassDescription</returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXAICPricesTransfer";
}
